class Probe:
    comparisons = 0

    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        Probe.comparisons += 1
        return self.value == other.value

    def __hash__(self):
        return hash(self.value)


def lookup_cost(n):
    items = [Probe(i) for i in range(n)]
    lookup = set(items)
    target = Probe(n - 1)
    Probe.comparisons = 0
    target in items
    list_cost = Probe.comparisons
    Probe.comparisons = 0
    target in lookup
    return list_cost, Probe.comparisons


